ghafjwsk7q","associated":{"chat":{"allowIncoming":"all","allowGroupInvites":"all"},"activitySubscription":{"allowSubscriptions":"followers"}},"labels":[],"createdAt":"2025-08-06T13:09:51.497Z"},{"did":"did:plc:pbjvqaziagcyv2vqodldn5op","handle":"felixs.dev","displayName":"Felix Schneider","avatar":"https://cdn.bsky.app/img/avatar/plain/did:plc:pbjvqaziagcyv2vqodldn5op/bafkreieedhblw2ljvpmoec7xkby7q5k5uw767rnor4sbjjwrdlsv7fuvei","associated":{"chat":{"allowIncoming":"all","allowGroupInvites":"all"},"activitySubscription":{"allowSubscriptions":"followers"}},"labels":[],"createdAt":"2024-12-30T07:33:46.442Z"},{"did":"did:plc:tsjjh5uzepibeoujgscgfgo4","handle":"jaredlemler.com","displayName":"Jared Lemler","avatar":"https://cdn.bsky.app/img/avatar/plain/did:plc:tsjjh5uzepibeoujgscgfgo4/bafkreiabiax3onjwvmnk4bodhtkks5vi7y2om2ki5fapfxuv3s24nneosq","associated":{"activitySubscription":{"allowSubscriptions":"followers"},"germ":{"showButtonTo":"usersIFollow","messageMeUrl":"https://landing.ger.mx/newUser"}},"labels":[],"createdAt":"2025-05-27T13:13:00.740Z"}],"$type":"app.bsky.embed.external#viewArticle"},"associatedRefs":[{"uri":"at://did:plc:ifn645rwvsuolxg7o3w7ouo4/site.standard.document/3mwqgs7dp2s2a","cid":"bafyreihcxcofz3zyrmgismvprjradsr7srdmaqy2y6ze7nt5slasfr3bsm","$type":"com.atproto.repo.strongRef"},{"uri":"at://did:plc:ifn645rwvsuolxg7o3w7ouo4/site.standard.publication/3mvimt7nmrs2m","cid":"bafyreic6arm47nzk5symkeafndsqjbtwbbb3pmne6qpgycpfwaowcrunnq","$type":"com.atproto.repo.strongRef"}],"associatedRecords":[{"$type":"site.standard.document","bskyPostRef":{"cid":"bafyreiesf6zo5wqojuoxdekbqap7pqev6t6xa2q5kzayntr6bgrt2ixi7m","commit":{"cid":"bafyreifs4tbwr5dn5qed4huad36f3m6d5gypp3eqvsknskk4nfifo3kdya","rev":"3mwqgsdcah222"},"uri":"at://did:plc:ifn645rwvsuolxg7o3w7ouo4/app.bsky.feed.post/3mwqgsd4cgs2a","validationStatus":"valid"},"content":{"$type":"pub.leaflet.content","pages":[{"$type":"pub.leaflet.pages.linearDocument","blocks":[{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","plaintext":"In 1989, the Web was invented to help researchers at CERN more easily share ideas and communicate. The incredible growth of the internet that came after needs no further introduction. Yet in 2026, the original goals of the internet seem to have waned: the research community is fragmented across walled garden communities, basic tools and utilities require extortionate subscriptions paid to for-profit companies, and scientific publishing is controlled by a cartel of publishers who monetize work conducted in the public good. We believe that the full value of the internet has not been achieved for research, and today, we're excited to announce a new not-for-profit initiative to try and help to fix that."}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","facets":[{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"http://aster.id/"}],"index":{"byteEnd":8,"byteStart":0}},{"features":[{"$type":"pub.leaflet.richtext.facet#footnote","contentPlaintext":"When we say researchers, we mean it broadly: obviously academics and students, but also independent scholars, citizen scientists, participatory and community-based researchers, research software engineers, librarians and archivists, and anyone doing careful, systematic inquiry into how the world works. Exactly where the lines fall, and how to verify researchers without becoming gatekeepers, is one of the open questions we want to work through with you!","footnoteId":"01a0a168-d925-7009-8b45-4e27110b92ea"}],"index":{"byteEnd":57,"byteStart":56}},{"features":[{"$type":"pub.leaflet.richtext.facet#footnote","contentFacets":[{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://lab.leaflet.pub/3mrq6ma5dgs2x"}],"index":{"byteEnd":277,"byteStart":240}}],"contentPlaintext":"The Atmosphere is an ecosystem of social networking apps that all use a common account. Atmosphere apps seamlessly integrate with each other and are designed so that they can't lock you in to extract your data for profit. For more info see https://lab.leaflet.pub/3mrq6ma5dgs2x","footnoteId":"01a0b5cd-e370-7774-ba18-ec5f05d11150"}],"index":{"byteEnd":217,"byteStart":216}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://blackskyweb.xyz/"}],"index":{"byteEnd":326,"byteStart":318}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://eurosky.tech/"}],"index":{"byteEnd":337,"byteStart":330}}],"plaintext":"Aster.id provides an account and hosting for researchers* on the open web: a place where you build and own your identity (@you.aster.id), website, data and connections. An Aster ID is an entry point to the Atmosphere*: the world of apps and services built on the AT Protocol, the technology that powers Bluesky. Think Blacksky or Eurosky, but for researchers."}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","facets":[{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://atproto.science/"}],"index":{"byteEnd":114,"byteStart":105}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://atproto.science/ecosystem/"}],"index":{"byteEnd":205,"byteStart":188}}],"plaintext":"Your Aster ID gives you access not just to Bluesky, but to a vibrant ecosystem of apps and in particular ATScience - the slice of the Atmosphere geared towards researchers, including over 30 apps and tools for publishing, data sharing, annotation, curation and more! This means that even if traditional social media (e.g., general micro-blogging platforms like Bluesky) isn't your jam, there are many more apps you can benefit from as a researcher."}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","facets":[{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://www.modalfoundation.org/"}],"index":{"byteEnd":157,"byteStart":141}}],"plaintext":"Aster joins ATScience as a non-profit, open-source, community-led initiative of researchers and builders, fiscally and legally hosted by the Modal Foundation."}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.header","level":2,"plaintext":"Why now?"}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.header","level":3,"plaintext":"Science social media has great potential but lacks a home"}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","plaintext":"The last few years have not been great for science. Public trust is at historic lows, and research is straining under mounting pressures — not least the way we publish and communicate science, which is long overdue for an upgrade."}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","plaintext":"Social media has a pivotal role to play in the next evolution of science: it’s a vital communication network both for researchers among themselves as well as with the broader public. Many would love to see it evolve to support new forms of science publishing, review and curation. And it’s a democratizing force in science, enabling the public to participate more directly in the process of research."}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","facets":[{"features":[{"$type":"pub.leaflet.richtext.facet#bold"}],"index":{"byteEnd":49,"byteStart":43}},{"features":[{"$type":"pub.leaflet.richtext.facet#bold"}],"index":{"byteEnd":266,"byteStart":263}}],"plaintext":"But science social media has lacked a real home. For a few short years, the science scene on Twitter (or Science Twitter as it was affectionately known) felt like it, opening our eyes to the vast potential of social media for researchers. But it never really was our home, as the restructuring of Twitter made painfully clear."}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.header","level":3,"plaintext":"The open web can be that home"}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","plaintext":"The loss of Science Twitter taught us a valuable lesson in what it means to have a home online. Home means controlling our platforms: accounts, data, algorithms, moderation and networks."}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","facets":[{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://www.sciencedirect.com/science/article/pii/S1751157725000641"}],"index":{"byteEnd":201,"byteStart":140}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"..."}],"index":{"byteEnd":397,"byteStart":389}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"..."}],"index":{"byteEnd":407,"byteStart":399}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"..."}],"index":{"byteEnd":419,"byteStart":412}}],"plaintext":"It also opened a unique opportunity: thousands of researchers migrated from Twitter to Bluesky, which now hosts a vibrant science community on par with Twitter in terms of the amount of research shared. Bluesky is part of the open web, meaning that it is built on open infrastructure (AT Protocol) that communities can run and shape according to their needs. For example, communities like Blacksky, Northsky and Eurosky run their own hosting, moderation and feeds. In the Atmosphere, apps can't lock you in since your account lives in a repository that belongs to you, not the app. So a user that doesn't agree with Bluesky's moderation policies can seamlessly migrate their account to a different host."}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.header","facets":[{"features":[{"$type":"pub.leaflet.richtext.facet#italic"}],"index":{"byteEnd":47,"byteStart":42}}],"level":3,"plaintext":"And researchers can shape it according to their unique needs"}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","facets":[{"features":[{"$type":"pub.leaflet.richtext.facet#footnote","contentFacets":[{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://bsky.app"}],"index":{"byteEnd":14,"byteStart":6}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://mu.social"}],"index":{"byteEnd":25,"byteStart":16}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://anisota.net"}],"index":{"byteEnd":38,"byteStart":27}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://tokimeki.blue/login"}],"index":{"byteEnd":53,"byteStart":40}}],"contentPlaintext":"e.g., bsky.app, mu.social, anisota.net, tokimeki.blue","footnoteId":"01a0b6f7-4ff2-7223-a124-40fc13032f03"}],"index":{"byteEnd":57,"byteStart":56}},{"features":[{"$type":"pub.leaflet.richtext.facet#footnote","contentFacets":[{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://leaflet.pub"}],"index":{"byteEnd":17,"byteStart":6}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://pckt.blog"}],"index":{"byteEnd":28,"byteStart":19}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://offprint.app"}],"index":{"byteEnd":42,"byteStart":30}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://lemma.pub"}],"index":{"byteEnd":53,"byteStart":44}}],"contentPlaintext":"e.g., leaflet.pub, pckt.blog, offprint.app, lemma.pub","footnoteId":"01a0b6f8-ef2b-7bb4-9382-9229b9d23992"}],"index":{"byteEnd":80,"byteStart":79}},{"features":[{"$type":"pub.leaflet.richtext.facet#footnote","contentFacets":[{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://tempomusic.app/"}],"index":{"byteEnd":20,"byteStart":6}}],"contentPlaintext":"e.g., tempomusic.app","footnoteId":"01a0b708-2c69-7bb4-9387-a1d78a9eddc3"}],"index":{"byteEnd":98,"byteStart":97}},{"features":[{"$type":"pub.leaflet.richtext.facet#footnote","contentFacets":[{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://tangled.org"}],"index":{"byteEnd":17,"byteStart":6}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://npmx.dev"}],"index":{"byteEnd":27,"byteStart":19}}],"contentPlaintext":"e.g., tangled.org, npmx.dev","footnoteId":"01a0b6fa-fdc7-7bb4-9384-d38ce21f4c1f"}],"index":{"byteEnd":107,"byteStart":106}},{"features":[{"$type":"pub.leaflet.richtext.facet#footnote","contentFacets":[{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://stream.place"}],"index":{"byteEnd":18,"byteStart":6}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://www.bluecast.app/"}],"index":{"byteEnd":32,"byteStart":20}}],"contentPlaintext":"e.g., stream.place, bluecast.app","footnoteId":"01a0b6fc-37b2-7bb4-9386-4a8df5d08021"}],"index":{"byteEnd":123,"byteStart":122}},{"features":[{"$type":"pub.leaflet.richtext.facet#footnote","contentFacets":[{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://atmosphere.money/"}],"index":{"byteEnd":22,"byteStart":6}}],"contentPlaintext":"e.g., atmosphere.money","footnoteId":"01a0cedf-8ae2-7994-b083-2bc2d438319e"}],"index":{"byteEnd":152,"byteStart":151}}],"plaintext":"The Atmosphere is a big place: it includes microblogging*, long-form publishing*, music discovery*, coding*, livestreaming*, and even funding platforms*."}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","facets":[{"features":[{"$type":"pub.leaflet.richtext.facet#didMention","did":"did:plc:7natp5xae72bddaqlkef2t4e"}],"index":{"byteEnd":167,"byteStart":157}},{"features":[{"$type":"pub.leaflet.richtext.facet#didMention","did":"did:plc:k7wclckeajmuibxbamtbejjg"}],"index":{"byteEnd":202,"byteStart":192}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://lea.ac/"}],"index":{"byteEnd":244,"byteStart":241}},{"features":[{"$type":"pub.leaflet.richtext.facet#didMention","did":"did:plc:uaadt6f5bbda6cycbmatcm3z"}],"index":{"byteEnd":289,"byteStart":266}},{"features":[{"$type":"pub.leaflet.richtext.facet#didMention","did":"did:plc:2f2ahswozqy4v5lvu676375y"}],"index":{"byteEnd":328,"byteStart":320}}],"plaintext":"Researchers can benefit from all of these, but we also have needs of our own. That's what the 30+ apps in ATScience are building for, including preprints on @chive.pub, collective curation on @semble.so, a client tailored for researchers on Lea, research feeds like @paper-feed.bsky.social, and professional profiles on @sifa.id . They all share the Atmosphere's superpower: one account that works everywhere, with your data and network following you rather than staying locked in an app. We're building Aster to be the identity and data hosting layer underpinning all of this potential for researchers on the Atmosphere — not for profit, and built by researchers, for researchers."}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","plaintext":"Aster also has lofty ambitions of its own, and we are incredibly excited to share some of our upcoming features supplementary to account hosting. First on our roadmap: personal websites for researchers that build and update themselves from your Aster data. More coming soon ✨"}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","plaintext":"We also plan to explore trust and verification services, which an identity provider is well placed to offer, and which matter more than ever in an age of AI-mediated science."}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.header","level":2,"plaintext":"Who’s behind Aster ID?"}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","facets":[{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://eurosky.tech/blog/3mgnjewfva22q/"}],"index":{"byteEnd":160,"byteStart":146}}],"plaintext":"The idea for Aster was sparked at Atmosphere Conf 2026 in follow up conversations after the ATScience workshop. A group of us were discussing the Eurosky launch and thought - why not try this for research, too?"}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","plaintext":"Currently, Aster is being developed by an expanded group of people from the original Atmosphere Conf discussion and the ATScience team. In the medium-term, we will expand Aster's governance to include members of its community and to be governed according to templates laid out by many other open source projects that exist in the public good."}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","facets":[{"features":[{"$type":"pub.leaflet.richtext.facet#italic"}],"index":{"byteEnd":74,"byteStart":69}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://openscholarlyinfrastructure.org/"}],"index":{"byteEnd":440,"byteStart":397}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://www.fulcrum.org/concern/monographs/h989r611r"}],"index":{"byteEnd":469,"byteStart":445}}],"plaintext":"On that note: Aster is a not-for-profit initiative. In fact, it will never be for profit. We are a collective of researchers building to benefit our community. That said, durably funding open research infrastructure is complex, as it requires balancing open science values with the challenges of long term sustainability. We will be following the evolving best practices in the space, such as the Principles of Open Scholarly Infrastructure and commons-based approaches to open-access science."}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.header","level":2,"plaintext":"Sounds great! When can I sign up?"}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","facets":[{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://www.iosp.science/"}],"index":{"byteEnd":57,"byteStart":48}}],"plaintext":"We're launching Aster as an invite-only beta at IOSP 2026 in Leiden (October 12–15), and will open up onboarding gradually from there."}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","facets":[{"features":[{"$type":"pub.leaflet.richtext.facet#code"}],"index":{"byteEnd":297,"byteStart":288}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://blackskyweb.xyz/"}],"index":{"byteEnd":516,"byteStart":508}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://eurosky.tech/"}],"index":{"byteEnd":525,"byteStart":518}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://northskysocial.ca/"}],"index":{"byteEnd":538,"byteStart":530}}],"plaintext":"Why start small? Running community infrastructure is hard, and there's plenty we're still figuring out —above all, how to balance openness with protection from abuse. We want Aster to welcome researchers of all kinds, including the many who work outside traditional institutions. But a .aster.id handle is only worth having if people can trust it. Luckily, we're in good company: the Atmosphere is already home to several wonderful community-run infrastructure projects that we're learning from, including Blacksky, Eurosky and Northsky."}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","facets":[{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://roomy.space/did:plc:b6csk4ofw7vpwrgz2aci57ey"}],"index":{"byteEnd":131,"byteStart":111}}],"plaintext":"We'll be working through these questions in the open. Subscribe to our blog to stay tuned (and weigh in!), and join our Roomy space if you want to get more involved. We also have a few more details on our FAQ page."}},{"$type":"pub.leaflet.pages.linearDocument#block","block":{"$type":"pub.leaflet.blocks.text","facets":[{"features":[{"$type":"pub.leaflet.richtext.facet#didMention","did":"did:plc:7axcqwj4roha6mqpdhpdwczx"}],"index":{"byteEnd":40,"byteStart":28}},{"features":[{"$type":"pub.leaflet.richtext.facet#link","uri":"https://www.modalfoundation.org/"}],"index":{"byteEnd":112,"byteStart":96}},{"features":[{"$type":"pub.leaflet.richtext.facet#didMention","did":"did:plc:ygxc7x6f7u3smp3j4m67duvy"}],"index":{"byteEnd":208,"byteStart":185}}],"plaintext":"Finally, a big thank you to @wang.social for the generous grant that got us started, and to the Modal Foundation for hosting our project fiscally and legally. To Eurosky and especially @spotchi.eurosky.social for the awesome tech stack support. And of course to all the lovely individuals on the ATScience Roomy and Signal chats who are investing the time and energy to make this real."}}],"id":"01a0a168-18fa-7991-bb98-29018aa76c06"}]},"contributors":[{"did":"did:plc:rtf3bjc3w2yn4syxtm4r7jt2"},{"did":"did:plc:ifn645rwvsuolxg7o3w7ouo4"},{"did":"did:plc:6i6n57nrkq6xavqbdo6bvkqr"},{"did":"did:plc:jcoy7v3a2t4rcfdh6i4kza25"},{"did":"did:plc:2zxlmj2dvub7smpul2lvwqfk"}],"coverImage":{"$type":"blob","ref":{"$link":"bafkreidvntdnpe3nzj7wkdxjuhutbf5g7lozznoe7gosqgw3xc2mx3i3om"},"mimeType":"image/webp","size":24306},"description":"","path":"/3mwqgs7dp2s2a","publishedAt":"2026-09-30T13:22:17.189Z","site":"at://did:plc:ifn645rwvsuolxg7o3w7ouo4/site.standard.publication/3mvimt7nmrs2m","tags":["atproto-science","announcement"],"title":"Announcing Aster - a home for researchers on the open web "},{"$type":"site.standard.publication","basicTheme":{"$type":"site.standard.theme.basic","accent":{"$type":"site.standard.theme.color#rgb","b":126,"g":42,"r":59},"accentForeground":{"$type":"site.standard.theme.color#rgb","b":255,"g":255,"r":255},"background":{"$type":"site.standard.theme.color#rgb","b":250,"g":252,"r":253},"foreground":{"$type":"site.standard.theme.color#rgb","b":0,"g":0,"r":0}},"description":"","icon":{"$type":"blob","ref":{"$link":"bafkreia2oxf6i34p25yfny2joydlaqpgkzn2x7pipstjayrx7oziw7ue4i"},"mimeType":"image/webp","size":3054},"name":"Aster Blog","preferences":{"prevNextDirection":"rtl","showComments":true,"showFirstLast":false,"showInDiscover":true,"showMentions":true,"showOtherPublicationsInTags":true,"showPrevNext":true,"showRecommends":true},"theme":{"$type":"pub.leaflet.publication#theme","accentBackground":{"$type":"pub.leaflet.theme.color#rgb","b":126,"g":42,"r":59},"accentText":{"$type":"pub.leaflet.theme.color#rgb","b":255,"g":255,"r":255},"backgroundColor":{"$type":"pub.leaflet.theme.color#rgba","a":100,"b":250,"g":252,"r":253},"backgroundImage":{"$type":"pub.leaflet.theme.backgroundImage","image":{"$type":"blob","ref":{"$link":"bafkreife3dusaimqs7te2o7uhvpps27oi2nlv6luqqfgcdzk2l4vikydbe"},"mimeType":"image/webp","size":762046},"repeat":false},"bodyFont":"custom:Fira Sans:Fira+Sans:ital,wght@0,400;0,700;1,400;1,700","headingFont":"custom:Playfair Display:Playfair+Display:ital,wght@0,400;0,700;1,400;1,700","pageBackground":{"$type":"pub.leaflet.theme.color#rgba","a":100,"b":241,"g":245,"r":247},"pageWidth":768,"primary":{"$type":"pub.leaflet.theme.color#rgb","b":39,"g":39,"r":39},"showPageBackground":true},"url":"https://blog.aster.place"}]}
            """;
        using TestServer server = TestServerBuilder.CreateServer(TestServerBuilder.DefaultUri, async context =>
        {
            Assert.Equal("/xrpc/app.bsky.embed.getEmbedExternalView", context.Request.Path);
            context.Response.ContentType = "application/json";
            await context.Response.WriteAsync(json, TestContext.Current.CancellationToken);
        });
        using HttpClient client = server.CreateClient();
        AtProtoHttpResult<EmbeddedExternalViewResponse> result = await BlueskyServer.GetEmbedExternalViewResponse(
            new Uri("https://blog.aster.place/3mwqgs7dp2s2a"),
            new AtUri("at://did:plc:ifn645rwvsuolxg7o3w7ouo4/site.standard.document/3mwqgs7dp2s2a"),
            null, TestServerBuilder.DefaultUri, null, client,
            cancellationToken: TestContext.Current.CancellationToken);

        Assert.True(result.Succeeded);
        ArticleView? article = result.Result.DeserializeData(
            (JsonTypeInfo<ArticleView>)BlueskyServer.BlueskyJsonSerializerOptions.GetTypeInfo(typeof(ArticleView)));
        Assert.NotNull(article);
        Assert.NotNull(article.Publisher);
        Assert.NotNull(result.Result.Data);
        Assert.Equal("app.bsky.embed.external#viewArticle", result.Result.Data.Value.GetProperty("$type").GetString());
    }

    [Fact]
    public void ProfileCaptureWithoutLinksRemainsCompatible()
    {
        // Public unauthenticated capture: HTTP 200, 2026-10-15T20:10:40Z.
        // Source: https://public.api.bsky.app/xrpc/app.bsky.actor.getProfile?actor=bsky.app
        // Observed: Detailed profile without links.
        const string json = """
            {"did":"did:plc:z72i7hdynmk6r22z27h6tvur","handle":"bsky.app","displayName":"Bluesky","avatar":"https://cdn.bsky.app/img/avatar/plain/did:plc:z72i7hdynmk6r22z27h6tvur/bafkreihwihm6kpd6zuwhhlro75p5qks5qtrcu55jp3gddbfjsieiv7wuka","associated":{"lists":18,"feedgens":7,"starterPacks":15,"labeler":false,"chat":{"allowIncoming":"none"},"activitySubscription":{"allowSubscriptions":"followers"}},"labels":[],"createdAt":"2023-04-12T04:53:57.057Z","verification":{"verifications":[],"verifiedStatus":"none","trustedVerifierStatus":"valid"},"description":"official Bluesky account (check username👆)\n\nBugs, feature requests, feedback: support@bsky.app","indexedAt":"2025-10-27T21:05:26.152Z","banner":"https://cdn.bsky.app/img/banner/plain/did:plc:z72i7hdynmk6r22z27h6tvur/bafkreichzyovokfzmymz36p5jibbjrhsur6n7hjnzxrpbt5jaydp2szvna","followersCount":35268345,"followsCount":21,"postsCount":876,"pinnedPost":{"cid":"bafyreicnt42y6vo6pfpvyro234ac4o6ijug6adwwrh7awflgrqlt4zibxq","uri":"at://did:plc:z72i7hdynmk6r22z27h6tvur/app.bsky.feed.post/3l6oveex3ii2l"}}
            """;
        ProfileViewDetailed? profile = JsonSerializer.Deserialize<ProfileViewDetailed>(json, BlueskyServer.BlueskyJsonSerializerOptions);

        Assert.NotNull(profile);
        Assert.Equal("bsky.app", profile.Handle.ToString());
        Assert.Null(profile.Links);
    }
